import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.xeBd2WE1.js";const h=JSON.parse('{"title":"AI 动态 · 2026-10-03","description":"","frontmatter":{"title":"AI 动态 · 2026-10-03","date":"2026-10-03T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-10/ai-news-2026-10-03.md","filePath":"news/2026-10/ai-news-2026-10-03.md","lastUpdated":null}'),r={name:"news/2026-10/ai-news-2026-10-03.md"};function i(l,e,o,c,p,d){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-动态-·-2026-10-03" tabindex="-1">AI 动态 · 2026-10-03 <a class="header-anchor" href="#ai-动态-·-2026-10-03" aria-label="Permalink to &quot;AI 动态 · 2026-10-03&quot;">​</a></h1><blockquote><p>截至 2026-10-03。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="苹果收紧-macos-完全磁盘访问权限-应对-ai-agent-风险" tabindex="-1">苹果收紧 macOS 完全磁盘访问权限，应对 AI Agent 风险 <a class="header-anchor" href="#苹果收紧-macos-完全磁盘访问权限-应对-ai-agent-风险" aria-label="Permalink to &quot;苹果收紧 macOS 完全磁盘访问权限，应对 AI Agent 风险&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-10-03">2026-10-03</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/77bc7ea62ab4.jpg" alt="配图"></p><p>苹果宣布为 macOS 的「完全磁盘访问」增加新管控，理由是能力越来越强的 AI Agent 让应用广泛读取用户文件、消息、邮件与浏览历史的风险显著上升。新机制要求用户以非常明确的动作才能授予该权限。对读者：桌面端 Agent 产品需提前适配权限弹窗与降级路径，否则可能在上线后遭遇大面积功能失效。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/02/apple-says-its-tightening-macos-full-disk-access-controls-due-to-new-risks-from-ai-agents/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="muse-会为你的亲友生成详细画像" tabindex="-1">Muse 会为你的亲友生成详细画像 <a class="header-anchor" href="#muse-会为你的亲友生成详细画像" aria-label="Permalink to &quot;Muse 会为你的亲友生成详细画像&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Wired AI</span><time datetime="2026-10-03">2026-10-03</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/2ec363bdd9af.jpg" alt="配图"></p><p>WIRED 报道称，Meta 的 AI Agent Muse 已被数百万用户下载，但它会为用户的亲友建立详细个人档案，便利背后是明确的隐私代价。报道将其与苹果收紧磁盘权限的举措放在同一背景下观察。对读者：涉及通讯录、聊天记录读取的 Agent 功能，建议在隐私政策中显式披露画像用途并给出关闭开关。</p><p class="news-entry-source"><a href="https://www.wired.com/story/muse-creates-detailed-profiles-of-all-your-friends-and-family/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="openai-安全透明度负责人离职并公开示警" tabindex="-1">OpenAI 安全透明度负责人离职并公开示警 <a class="header-anchor" href="#openai-安全透明度负责人离职并公开示警" aria-label="Permalink to &quot;OpenAI 安全透明度负责人离职并公开示警&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-10-03">2026-10-03</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/bf95006d68c1.jpg" alt="配图"></p><p>David Robinson 此前负责为 OpenAI 每次重大模型发布撰写安全报告，本周他辞职并在《大西洋月刊》撰文，称行业文化「已经坏掉」，问题不是加几条新规就能解决。对读者：把模型供应商的安全团队稳定性纳入采购尽调清单，人员动荡往往先于合规风险暴露。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/1004408/openai-safety-quits-sounding-the-alarm" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="openai-安全团队持续震荡-负责人离职、三人因泄密被开" tabindex="-1">OpenAI 安全团队持续震荡：负责人离职、三人因泄密被开 <a class="header-anchor" href="#openai-安全团队持续震荡-负责人离职、三人因泄密被开" aria-label="Permalink to &quot;OpenAI 安全团队持续震荡：负责人离职、三人因泄密被开&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-10-03">2026-10-03</time></p><p>量子位报道，OpenAI 安全透明度负责人 David Robinson 离职，同时有三名员工因泄密被解雇，安全团队接连出现人事变动。Robinson 团队原本负责评估、红队测试与模型部署决策，并为每次发布撰写 system card。对读者：关注后续 system card 的署名与质量变化，这是判断模型安全披露是否缩水的直接信号。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/10/501368.html" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="openai-推出企业向-agent-平台-dots-可代订晚餐" tabindex="-1">OpenAI 推出企业向 Agent 平台 Dots，可代订晚餐 <a class="header-anchor" href="#openai-推出企业向-agent-平台-dots-可代订晚餐" aria-label="Permalink to &quot;OpenAI 推出企业向 Agent 平台 Dots，可代订晚餐&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-10-03">2026-10-03</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/3c8d6b8a6da6.jpg" alt="配图"></p><p>OpenAI 本周发布 Agent 平台 Dots，定位偏工作场景，形态是带拟人化头像、可自定义名字的小助手，目前每人一个，未来支持多个。它像办公软件，但也能处理订餐等生活事务。对读者：评估企业 Agent 平台时，重点看它与现有办公系统的权限打通，而非头像可爱程度。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/1004096/openai-chatgpt-dots-hands-on-agent" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="英伟达发布-dgx-spark-64gb-1-petaflop-桌面级本地-ai-主机" tabindex="-1">英伟达发布 DGX Spark 64GB：1 PetaFLOP 桌面级本地 AI 主机 <a class="header-anchor" href="#英伟达发布-dgx-spark-64gb-1-petaflop-桌面级本地-ai-主机" aria-label="Permalink to &quot;英伟达发布 DGX Spark 64GB：1 PetaFLOP 桌面级本地 AI 主机&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-03">2026-10-03</time></p><p>英伟达宣布 DGX Spark 64GB，采用 Grace Blackwell 架构，提供约 1 PetaFLOP 算力，面向本地 AI Agent、模型微调与推理场景，定位为桌面级设备。对读者：若团队有数据不出内网的硬性要求，可把这类设备纳入本地推理与微调的选型对比，重点核算显存与并发。</p><p class="news-entry-source"><a href="https://news.google.?oc=5" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="prime-intellect-推出-prime-inference-面向前沿开源模型的托管推理" tabindex="-1">Prime Intellect 推出 Prime Inference：面向前沿开源模型的托管推理 <a class="header-anchor" href="#prime-intellect-推出-prime-inference-面向前沿开源模型的托管推理" aria-label="Permalink to &quot;Prime Intellect 推出 Prime Inference：面向前沿开源模型的托管推理&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-03">2026-10-03</time></p><p>Prime Intellect 发布 Prime Inference，为前沿开源模型提供无服务器与预留两种推理服务形态，方便开发者按需或按容量调用开源权重模型。对读者：在闭源 API 与自建推理之间做成本对比时，可把这类托管开源推理作为中间选项纳入评估。</p><p class="news-entry-source"><a href="https://news.google.?oc=5" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="meta-开源-muse-硬件代码-可自制-ai-小设备" tabindex="-1">Meta 开源 Muse 硬件代码，可自制 AI 小设备 <a class="header-anchor" href="#meta-开源-muse-硬件代码-可自制-ai-小设备" aria-label="Permalink to &quot;Meta 开源 Muse 硬件代码，可自制 AI 小设备&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-10-03">2026-10-03</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/04039d505985.jpg" alt="配图"></p><p>Meta 开源了让开发者自制 Muse AI 设备的代码，可在 ESP32 开发板或树莓派上接入 Muse，并连接屏幕、按键、传感器与执行器。官方示例包括用彩色电子墨水屏显示提醒、做成 HDMI 棒投屏、或做成小型触屏设备。对读者：想快速验证端侧 Agent 形态的团队，可先用 ESP32 跑通最小闭环再谈量产。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/1004330/meta-muse-ai-gadgets-home-link" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="mit-与-sakana-ai-提出用-llm-评审降低自改进编码-agent-的评估成本" tabindex="-1">MIT 与 Sakana AI 提出用 LLM 评审降低自改进编码 Agent 的评估成本 <a class="header-anchor" href="#mit-与-sakana-ai-提出用-llm-评审降低自改进编码-agent-的评估成本" aria-label="Permalink to &quot;MIT 与 Sakana AI 提出用 LLM 评审降低自改进编码 Agent 的评估成本&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">VentureBeat AI</span><time datetime="2026-10-03">2026-10-03</time></p><p>MIT 与 Sakana AI 联合提出新框架，用 LLM 作为评审者来评估自我改进的编码 Agent，从而削减评估环节的开销。该思路针对的是编码 Agent 迭代中反复跑测试与人工评审成本过高的问题。对读者：自建编码 Agent 评估流水线时，可尝试用模型评审替代部分人工回归，但需保留抽样人工校验以防评审漂移。</p><p class="news-entry-source"><a href="https://news.google.?oc=5" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="ibm-将-bob-带入自托管与气隙环境-代码不出内网的-agentic-开发" tabindex="-1">IBM 将 Bob 带入自托管与气隙环境：代码不出内网的 Agentic 开发 <a class="header-anchor" href="#ibm-将-bob-带入自托管与气隙环境-代码不出内网的-agentic-开发" aria-label="Permalink to &quot;IBM 将 Bob 带入自托管与气隙环境：代码不出内网的 Agentic 开发&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-03">2026-10-03</time></p><p>IBM 把 Bob 推向自托管与气隙（air-gapped）环境，让企业在不移动代码的前提下使用 Agentic 软件开发能力。这切中的是金融、政企等对代码外流极度敏感的团队。对读者：受合规限制无法使用公有云编码助手的团队，可把自托管 Agent 方案列入下一轮工具评估。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMinwFBVV95cUxPUmtDcGxhamdVbC0weWd0ZVA2SE1QX0d3OFlXUlAwdl9YbHlyY0ZPdTBzNHNZY1kyZEQyTURmMkhJN3ZJdGt2SnItZ3JMLTB6U2hwTUVXa0FlUmJWY090ZkVhMWVKa2RpTEJCeFVobzVBS2tjOUR3QjhaRmpMbEc4S1VoZXplYzJxZUhMWTY0MlgwcTVVLXRjZUJEaC1xdW8?oc=5" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div>',8)])])}const g=a(r,[["render",i]]);export{h as __pageData,g as default};
